(() => { const reduced = matchMedia('(prefers-reduced-motion: reduce)').matches; const progress = document.querySelector('.scroll-progress'); const update = () => { if (progress) progress.style.transform = `scaleX(${scrollY / Math.max(1,document.documentElement.scrollHeight-innerHeight)})`; }; addEventListener('scroll', update, {passive:true}); update(); if (!reduced && 'IntersectionObserver' in window) { const io = new IntersectionObserver(es => es.forEach(e => e.isIntersecting && e.target.classList.add('is-visible')), {threshold:.12}); document.querySelectorAll('[data-reveal]').forEach(e => io.observe(e)); } document.querySelector('[data-theme-toggle]')?.addEventListener('click', () => { const next = document.documentElement.dataset.theme === 'light' ? 'dark' : 'light'; document.documentElement.dataset.theme = next; localStorage.setItem('fedos-theme', next); }); const saved = localStorage.getItem('fedos-theme'); if (saved) document.documentElement.dataset.theme = saved; })();
